var _mmTapGuard=false;
function _handleMiniMapClosedTap(e){
  if(e){
    if(e.cancelable)e.preventDefault();
    e.stopPropagation();
  }
  if(!mc||!mm)return;
  if(mmExp)return;
  if(mapTransitioning)return;
  if(_mmTapGuard)return;
  _mmTapGuard=true;
  setTimeout(function(){_mmTapGuard=false;},800);
  toggleMap();
}
