const ROAST_LB_KEY='roast_visitor_id';const ROAST_COUNT_KEY='roast_local_count';const ROAST_ZONE_KEY='roast_zone_stats';
function getVisitorId(){let id=localStorage.getItem(ROAST_LB_KEY);if(!id){id='v_'+Math.random().toString(36).substr(2,9)+'_'+Date.now().toString(36);localStorage.setItem(ROAST_LB_KEY,id);}return id;}
