function getRoastRank(count){if(count>=100)return{title:'🏆 ROAST GOD',color:'#FFD700'};if(count>=50)return{title:'🔥 FLAME MASTER',color:'#FF6B35'};if(count>=25)return{title:'😈 SAVAGE READER',color:'#E53935'};if(count>=10)return{title:'😤 GETTING SPICY',color:'#FF9800'};if(count>=5)return{title:'🌶️ WARMING UP',color:'#FFC107'};return{title:'🥚 ROOKIE',color:'#9E9E9E'};}
function buildLeaderboardPanel(){if(document.getElementById('roastLeaderboard'))return;const panel=document.createElement('div');panel.id='roastLeaderboard';panel.className='roast-lb-panel';panel.innerHTML='<div class="rlb-header"><div class="rlb-title">🔥 ROAST LEADERBOARD</div><div class="rlb-close" id="rlbClose">✕</div></div><div class="rlb-you"><div class="rlb-you-label">YOUR STATS</div><div class="rlb-you-name"><input id="rlbNameInput" type="text" maxlength="20" placeholder="Enter your name..." value="'+(localStorage.getItem('roast_visitor_name')||'')+'"><button id="rlbNameSave">💾</button></div><div class="rlb-you-count"><span id="rlbYourCount">'+getLocalRoastCount()+'</span> roasts read</div><div class="rlb-you-rank" id="rlbYourRank"></div><div class="rlb-zone-breakdown" id="rlbZoneBreakdown"></div></div><div class="rlb-divider"></div><div class="rlb-list-header">TOP ROASTERS</div><div class="rlb-list" id="rlbList"><div class="rlb-loading">Loading...</div></div>';document.body.appendChild(panel);document.getElementById('rlbClose').addEventListener('click',()=>{panel.classList.remove('open');});document.getElementById('rlbNameSave').addEventListener('click',()=>{const name=document.getElementById('rlbNameInput').value.trim();if(name){localStorage.setItem('roast_visitor_name',name);syncLeaderboard();if(typeof playSfx==='function')playSfx('pop');}});updateLeaderboardStats();}
async function updateLeaderboardStats(){const count=getLocalRoastCount();const rank=getRoastRank(count);const rankEl=document.getElementById('rlbYourRank');if(rankEl){rankEl.textContent=rank.title;rankEl.style.color=rank.color;}const countEl=document.getElementById('rlbYourCount');if(countEl)countEl.textContent=count;const stats=getLocalZoneStats();const breakdown=document.getElementById('rlbZoneBreakdown');if(breakdown){const zones=['introduction','work','portfolio','hobby','fun'];const labels={introduction:'📸 Intro',work:'🎯 Work',portfolio:'🚀 Portfolio',hobby:'🎮 Hobby',fun:'😂 Fun'};let html='';zones.forEach(z=>{const pm=stats[z+'_pm']||0;const corp=stats[z+'_corp']||0;const total=pm+corp;if(total>0)html+='<div class="rlb-zone-row"><span class="rlb-zone-name">'+labels[z]+'</span><span class="rlb-zone-count">'+total+'</span></div>';});breakdown.innerHTML=html||'<div style="font-size:0.6rem;color:rgba(255,255,255,0.3);text-align:center;padding:4px">Tap some roasts to see zone stats!</div>';}const data=await fetchLeaderboard();const list=document.getElementById('rlbList');if(list&&data.length){const vid=getVisitorId();list.innerHTML=data.map((entry,i)=>{const r=getRoastRank(entry.roast_count);const medal=i===0?'🥇':i===1?'🥈':i===2?'🥉':'';const isYou=entry.visitor_name===(localStorage.getItem('roast_visitor_name')||'');return'<div class="rlb-row'+(isYou?' rlb-row-you':'')+'"><span class="rlb-pos">'+(medal||(i+1))+'</span><span class="rlb-name">'+(entry.visitor_name||'Anonymous')+'</span><span class="rlb-score">'+entry.roast_count+'</span><span class="rlb-rank-badge" style="color:'+r.color+'">'+r.title.split(' ')[0]+'</span></div>';}).join('');}else if(list){list.innerHTML='<div style="text-align:center;padding:20px;color:rgba(255,255,255,0.4);font-size:0.7rem">No roasters yet. Be the first! 🔥</div>';}}
function toggleLeaderboard(){buildLeaderboardPanel();const panel=document.getElementById('roastLeaderboard');if(panel){panel.classList.toggle('open');if(panel.classList.contains('open'))updateLeaderboardStats();}}
function spawnEmbers(cx,cy){var count=IS_LOW_POWER_DEVICE?3:8;for(let i=0;i<count;i++){const em=document.createElement('div');em.className='roast-ember';const colors=['#FF6B35','#FFD700','#FF4500','#FF8C00','#FFA500'];em.style.background=colors[Math.floor(Math.random()*colors.length)];em.style.left=(cx+(Math.random()-0.5)*40)+'px';em.style.top=(cy-Math.random()*10)+'px';em.style.width=(3+Math.random()*5)+'px';em.style.height=em.style.width;em.style.animationDuration=(0.4+Math.random()*0.5)+'s';em.style.boxShadow='0 0 4px '+em.style.background;document.body.appendChild(em);setTimeout(()=>em.remove(),900);}}
